#!/usr/bin/env python3
"""Build the complete dependency-free Isak Fire website from shared content."""
import json
from html import escape as e
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'dist'
DATA = json.loads((ROOT / 'content.json').read_text())
SERVICES, LOCATIONS = DATA['services'], DATA['locations']
PAY = 'https://buy.stripe.com/eVa4iy7Qqbsk5CUeUV'
ARROW = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>'
DIAG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg>'
PATHS = {
 'sprinkler':'M12 3v8M5 11h14M8 14l-3 6M12 15v6M16 14l3 6M8 7h8',
 'alarm':'M7 17V9a5 5 0 0 1 10 0v8M5 17h14M10 21h4M3 4l2 2M21 4l-2 2',
 'flame':'M13 2c1 6-5 6-5 11-2-1-2-3-2-3-5 9 1 12 6 12s10-4 7-10c-1 3-3 3-3 3 1-7-3-13-3-13Z',
 'extinguisher':'M9 7h7v14H7V7h2ZM10 7V3h5M11 3 8 1M15 3h4v8M7 12h9',
 'signal':'M12 18v3M12 12a2 2 0 1 0 0 .1M7 16a7 7 0 0 1 0-10M17 16a7 7 0 0 0 0-10M3 19a12 12 0 0 1 0-16M21 19a12 12 0 0 0 0-16',
 'gauge':'M4 18a10 10 0 1 1 16 0ZM12 14l5-6M7 7l1 1M12 4v2M4 12h2M18 12h2',
 'valve':'M3 10h6V6h6v4h6v6h-6v4H9v-4H3ZM12 6V2M7 2h10',
 'exit':'M3 3h12v18H3ZM10 12h12M18 8l4 4-4 4M6 12h1',
 'shield':'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6ZM8 12l3 3 5-6',
 'building':'M4 21V7h7V3h9v18ZM8 10v2M8 15v2M15 7h2M15 11h2M15 15h2M11 21v-4',
 'check':'M5 12l4 4L19 6',
 'pin':'M12 22s8-8 8-14A8 8 0 0 0 4 8c0 6 8 14 8 14ZM12 5a3 3 0 1 0 0 6 3 3 0 0 0 0-6',
 'plus':'M12 5v14M5 12h14',
 'mail':'M3 5h18v14H3ZM3 6l9 7 9-7',
 'phone':'M5 3h4l2 5-3 2a17 17 0 0 0 6 6l2-3 5 2v4c-10 5-23-8-16-16Z'
}
def icon(name):
 return f'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{PATHS.get(name,PATHS["shield"])}"/></svg>'
def button(text,href='/quote/',kind='',external=False):
 return f'<a class="button {kind}" href="{href}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+f'>{text}{DIAG if external else ARROW}</a>'
def textlink(text,href,external=False):
 return f'<a class="text-link" href="{href}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+f'>{text}{DIAG if external else ARROW}</a>'
def eyebrow(text): return f'<p class="eyebrow"><span></span>{text}</p>'
def image(name,alt,cls='',eager=False):
 dims = 'width="1024" height="1536"' if name=='technician' else 'width="1536" height="1024"'
 return f'<img class="{cls}" src="/assets/{name}.webp" alt="{alt}" {dims} '+('fetchpriority="high"' if eager else 'loading="lazy"')+' decoding="async">'
def logo(): return '<a class="brand" href="/" aria-label="Isak Fire Protection home"><img src="/assets/isak-logo.jpg" alt="Isak Fire Protection — Protecting lives and property" width="200" height="200"><span class="brand-caption">ISAK FIRE<br><small>PROTECTION</small></span></a>'
def header():
 nav=''.join(f'<a href="{u}">{t}</a>' for t,u in [('Services','/services/'),('Our company','/about/'),('Locations','/locations/'),('Resources','/resources/')])
 return f'''<a class="skip-link" href="#main">Skip to content</a>
 <div class="utility"><div class="container utility-inner"><span>Protecting lives. Preserving what matters.</span><div><a href="tel:+18333068200">Toll free (833) 306-8200</a><a href="/client-portal/">Client access</a><a href="/partners/">Partner access</a><a href="{PAY}" target="_blank" rel="noopener noreferrer">Pay an invoice ↗</a></div></div></div>
 <header class="site-header"><div class="container header-inner">{logo()}<nav aria-label="Main navigation">{nav}</nav><div class="header-actions">{button('Request a quote')}<button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="mobile-menu"><span></span><span></span></button></div></div></header>
 <dialog id="mobile-menu"><div class="mobile-top">{logo()}<button class="menu-close" aria-label="Close navigation">×</button></div><nav aria-label="Mobile navigation">{nav}<a href="/contact/">Contact</a><a href="/careers/">Careers</a></nav><div class="mobile-utility"><a href="/client-portal/">Client access</a><a href="/partners/">Partner access</a><a href="{PAY}" target="_blank" rel="noopener noreferrer">Pay an invoice ↗</a></div>{button('Request a quote')}<a class="mobile-phone" href="tel:+13124457787">(312) 445-7787</a></dialog>'''
def cta():
 return f'''<section class="closing"><div class="container closing-inner"><div>{eyebrow('LET’S TALK ABOUT YOUR PROPERTY')}<h2>What matters to you.<br><span>Matters to us.</span></h2></div><div><p>Bring us your plans, your questions<br>or your next inspection.</p>{button('Start a conversation','/quote/')}<a class="closing-phone" href="tel:+13124457787">Or call (312) 445-7787</a></div></div></section>'''
def footer():
 return f'''<footer><div class="container footer-main"><div class="footer-brand">{logo()}<p>Complete fire protection.<br>Considered from every angle.</p></div><div><h3>Protection</h3><a href="/services/">All services</a><a href="/services/fire-sprinklers/">Fire sprinklers</a><a href="/services/fire-alarms/">Alarms & detection</a><a href="/services/fire-suppression/">Special hazards</a></div><div><h3>Isak Fire</h3><a href="/about/">Our company</a><a href="/locations/">Our locations</a><a href="/careers/">Careers</a><a href="/contact/">Get in touch</a></div><div><h3>Here to help</h3><a href="/resources/">Questions & answers</a><a href="/insights/">News & insights</a><a href="/client-portal/">Client access</a><a href="/partners/">Partner access</a></div><div class="footer-contact"><h3>Talk to our team</h3><a href="tel:+13124457787">(312) 445-7787</a><a href="mailto:office@isakfire.com">office@isakfire.com</a><p>Mon–Fri · 8 AM–4 PM</p>{textlink('Pay an invoice',PAY,True)}</div></div><div class="container footer-bottom"><span>© 2026 Isak Fire Protection, Inc.</span><a href="https://isakfire.com/" target="_blank" rel="noopener noreferrer">Current website ↗</a><a href="#top">Back to top ↑</a></div><p class="container preview-note">Private design preview. The existing Isak Fire logo is retained. Equipment, building and team visuals are illustrative concepts. Quote details stay in your browser until you choose to open an email draft; this preview does not submit inquiries or provide portal access.</p></footer>'''
def page(path,title,body,description='',close=True):
 dest=OUT/path.strip('/')/'index.html' if path!='/' else OUT/'index.html'
 dest.parent.mkdir(parents=True,exist_ok=True)
 desc=description or 'Fire protection services, project planning and ongoing system care from Isak Fire Protection. Explore services and contact your local team.'
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Isak Fire Protection</title><meta name="description" content="{e(desc)}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#f7f8f7"><meta property="og:title" content="{e(title)} | Isak Fire Protection"><meta property="og:description" content="{e(desc)}"><link rel="icon" type="image/png" sizes="32x32" href="/assets/isak-favicon-32.png"><link rel="icon" type="image/png" sizes="96x96" href="/assets/isak-favicon-96.png"><link rel="shortcut icon" href="/favicon.ico"><link rel="preload" href="/assets/manrope.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script></head><body id="top">{header()}<main id="main">{body}{cta() if close else ''}</main>{footer()}</body></html>'''
 dest.write_text(html)
def subhero(label,title,desc,extra=''):
 return f'<section class="container page-hero">{eyebrow(label)}<h1>{title}</h1><div class="page-hero-bottom"><p>{desc}</p>{extra}</div></section>'
def service_rows(items):
 return ''.join(f'<a class="service-row" href="/services/{s["slug"]}/"><span class="service-icon">{icon(s["icon"])}</span><div><h3>{s["name"]}</h3><p>{s["description"]}</p></div><span class="round-arrow">{ARROW}</span></a>' for s in items)
def faq_items(items):
 return ''.join(f'<details class="faq" data-category="{e(f["group"])}"><summary>{e(f["q"])}{icon("plus")}</summary><p>{e(f["a"])}</p></details>' for f in items)
def news_cards(items):
 return ''.join(f'<article class="news-card" data-category="{e(n["category"])}"><div class="news-meta"><span>{n["category"]}</span><time>{n["date"]}</time></div><h3>{n["title"]}</h3><p>{n["topic"]}</p>{textlink("Read on Isak Fire","https://isakfire.com/news.html",True)}</article>' for n in items)

hero=f'''<section class="team-hero" aria-labelledby="hero-title"><div class="team-hero-media"><img src="/assets/isak-office-field-hero.webp" alt="Generated concept of a six-person Isak team in branded field uniforms, polos and office shirts beside an Isak service van" width="1672" height="941" fetchpriority="high" decoding="async"></div><div class="container team-hero-content"><div class="team-hero-copy">{eyebrow('FIRE PROTECTION. FULLY CONSIDERED.')}<h1 id="hero-title">Protection.<br><span>Without<br> compromise.</span></h1><p>For the people inside.<br>For everything you’ve built.</p><div class="team-hero-actions">{button('Protect your property')}{textlink('Explore our services','/services/')}</div><div class="team-hero-detail">{icon('shield')}<span>Design. Installation. Inspection. Ongoing care.</span></div></div></div><span class="team-hero-note">ISAK TEAM & FLEET · VISUAL CONCEPT</span></section>
 <section class="container proof-strip" aria-label="At a glance"><p>One property.<br><strong>Or an entire portfolio.</strong></p><div><strong>09</strong><span>Service disciplines</span></div><div><strong>06</strong><span>Regional locations</span></div><div><strong>US + CA</strong><span>United States & Canada</span></div></section>
 <section class="container intro-section reveal">{eyebrow('BECAUSE IT’S NEVER JUST A BUILDING')}<h2>It’s where people work.<br>Where ideas take shape.<br><span>Where life happens.</span></h2><p>Isak Fire Protection brings the systems, the service and the people together to help protect it. From your first drawing to your next inspection, we stay part of the picture.</p></section>
 <section class="services-section"><div class="container"><div class="section-heading reveal"><div>{eyebrow('COMPLETE FIRE PROTECTION')}<h2>Every system.<br><span>One accountable team.</span></h2></div>{textlink('All nine services','/services/')}</div><div class="service-showcase"><div class="showcase-intro"><span class="large-number">01—09</span><h3>Connected expertise.<br>Considered protection.</h3><p>Find the right starting point for your building. We’ll help you work through the details.</p><div class="sector-tags"><span>Commercial</span><span>Industrial</span><span>Residential</span></div></div><div class="service-browser"><div class="service-tabs" role="tablist" aria-label="Service groups"><button role="tab" id="tab-suppression" aria-controls="panel-suppression" aria-selected="true" data-service-tab="suppression">Suppression</button><button role="tab" id="tab-detection" aria-controls="panel-detection" aria-selected="false" tabindex="-1" data-service-tab="detection">Detection</button><button role="tab" id="tab-care" aria-controls="panel-care" aria-selected="false" tabindex="-1" data-service-tab="care">System care</button></div>'''+''.join(f'<div role="tabpanel" id="panel-{slug}" aria-labelledby="tab-{slug}"'+(' hidden' if i else '')+'>'+service_rows([s for s in SERVICES if s['group']==name])+'</div>' for i,(slug,name) in enumerate([('suppression','Suppression'),('detection','Detection'),('care','System care')]))+f'''</div></div></div></section>
 <section class="facility-section"><div class="facility-photo">{image('facility','Illustrative modern commercial building with a sunlit glass atrium')}<span class="concept-label">ILLUSTRATIVE PROPERTY</span></div><div class="container facility-copy"><div>{eyebrow('THINKING BEYOND INSTALLATION')}<h2>Built into your plans.<br><span>Part of your everyday.</span></h2></div><p>A considered protection program starts early and continues long after the handover.</p><div class="lifecycle"><article><span>01 / PLAN</span><h3>Get the details right.</h3><p>Design, project coordination and a scope built around your property.</p></article><article><span>02 / BUILD</span><h3>Bring it together.</h3><p>Installation for new construction, retrofits and evolving spaces.</p></article><article><span>03 / CARE</span><h3>Stay one step ahead.</h3><p>Inspection, testing, maintenance and clear records for the next decision.</p></article></div></div></section>
 <section class="container people-section"><div class="people-photo">{image('technician','Illustrative fire protection technician reviewing a tablet beside red riser pipes')}<span class="concept-label">ILLUSTRATIVE SERVICE SCENE</span></div><div class="people-copy reveal">{eyebrow('EXPERTISE WITH ACCOUNTABILITY')}<h2>Serious about<br>the systems.<br><span>Personal about<br>the service.</span></h2><p>Your property deserves a team that understands it. Isak brings design, field service and ongoing coordination into one conversation.</p><ul class="check-list"><li>{icon('check')}A team for the full system lifecycle</li><li>{icon('check')}Coordination with local authorities</li><li>{icon('check')}Support for multi-site portfolios</li></ul>{textlink('Get to know Isak','/about/')}</div></section>
 <section class="locations-preview"><div class="container location-layout"><div class="location-heading">{eyebrow('LOCAL KNOWLEDGE. SHARED STANDARDS.')}<h2>Closer to<br><span>what matters.</span></h2><p>Six locations. A connected team.<br>Find your local point of contact.</p>{textlink('Explore our locations','/locations/')}<small>Confirm service availability for your property.</small></div><div class="location-list">'''+''.join(f'<a href="/locations/#{l["city"].lower()}" class="location-row"><span>{str(i+1).zfill(2)}</span><h3>{l["city"]}</h3><p>{l["region"]}</p>{DIAG}</a>' for i,l in enumerate(LOCATIONS))+f'''</div></div></section>
 <section class="container journal-section"><div class="section-heading"> <div>{eyebrow('A CLEARER VIEW')}<h2>Knowledge is<br><span>part of protection.</span></h2></div>{textlink('News & insights','/insights/')}</div><div class="news-grid">{news_cards(DATA['insights'][:3])}</div></section>
 <section class="container faq-section"><div>{eyebrow('STRAIGHT ANSWERS')}<h2>A good place<br><span>to start.</span></h2>{textlink('All questions & answers','/resources/')}</div><div>{faq_items([DATA['faqs'][0],DATA['faqs'][1],DATA['faqs'][4],DATA['faqs'][9],DATA['faqs'][-1]])}</div></section>'''
page('/','Protection. Without compromise.',hero)

filters='<div class="filter-bar" role="group" aria-label="Filter services">'+''.join(f'<button data-filter="{v}" aria-pressed="{str(i==0).lower()}">{v}</button>' for i,v in enumerate(['All services','Suppression','Detection','System care']))+'</div>'
directory=''.join(f'<article class="service-directory-item" data-category="{s["group"]}"><span class="directory-index">{str(i+1).zfill(2)}</span>{icon(s["icon"])}<div><p class="small-label">{s["group"]}</p><h2><a href="/services/{s["slug"]}/">{s["name"]}</a></h2><p>{s["description"]}</p></div>{textlink("Explore service","/services/"+s['slug']+"/")}</article>' for i,s in enumerate(SERVICES))
page('/services/','Our services',subhero('NINE CONNECTED DISCIPLINES','Every system.<br><span>Every stage.</span>','A complete approach to fire protection, from the systems you install to the service that keeps them in view.',button('Discuss your property'))+f'<section class="container directory-section" data-filter-scope>{filters}<div class="service-directory">{directory}</div></section>')
for s in SERVICES:
 related=[x for x in SERVICES if x['group']==s['group'] and x['slug']!=s['slug']][:3]
 if not related: related=SERVICES[:2]
 body=subhero(s['group'].upper(),s['name']+'.',s['intro'],button('Request a quote','/quote/?service='+s['slug']))+f'''<section class="container service-detail"><div class="detail-visual">{image('hero' if s['group']=='Suppression' else 'technician','Illustrative fire protection '+('equipment' if s['group']=='Suppression' else 'service scene'))}<span class="concept-label">ILLUSTRATIVE CONCEPT</span></div><div><p class="lead">{s['detail']}</p><h2>Let’s look at the scope.</h2><ul class="detail-list">'''+''.join(f'<li>{icon("check")}{x}</li>' for x in s['items'])+f'''</ul><p class="muted">System suitability, service availability and applicable requirements are confirmed for your property.</p>{textlink('Talk to our team','/contact/')}</div></section><section class="container related"><div class="section-heading"><h2>Connected services.</h2>{textlink('View all services','/services/')}</div>{service_rows(related)}</section>'''
 page('/services/'+s['slug']+'/',s['name'],body,s['description'])

about=subhero('OUR COMPANY','Protection is a system.<br><span>Trust is a relationship.</span>','A fire protection partner for the places people count on, from a single property to a multi-building portfolio.')+f'''<div class="container wide-photo">{image('facility','Illustrative commercial office building')}<span class="concept-label">ILLUSTRATIVE PROPERTY</span></div><section class="container editorial"><h2>Built around<br>your property.</h2><div><p class="lead">Fire protection is more than equipment. It takes planning, careful installation, ongoing attention and people who stay accountable.</p><p>Isak Fire Protection brings those disciplines together. The team works across commercial, industrial and residential environments, with support for new construction, retrofits and existing systems.</p><p>From the initial scope to inspection records and corrective work, the goal is a clearer conversation about the protection your property needs.</p>{textlink('Explore the service disciplines','/services/')}</div></section><section class="container people-section about-people"><div class="people-photo">{image('technician','Illustrative technician documenting fire protection work')}<span class="concept-label">ILLUSTRATIVE SERVICE SCENE</span></div><div><p class="eyebrow">ONE TEAM. THROUGH EVERY STAGE.</p><h2>Show up.<br>Follow through.<br><span>Stay accountable.</span></h2><p class="lead">Local knowledge and a connected team support each project, each service visit and each next step.</p><div class="values"><h3>Consider the whole property.</h3><p>Understand the building, the people and the systems together.</p><h3>Make the details clear.</h3><p>Discuss scope, documentation and responsibilities from the start.</p><h3>Think beyond handover.</h3><p>Plan for inspections, service and the next chapter of your building.</p></div></div></section>'''
page('/about/','Our company',about)

locations=subhero('SIX LOCATIONS. ONE CONNECTED TEAM.','Find your<br><span>local connection.</span>','Contact the team serving your area. For projects beyond these regions, call us to discuss availability.',button('Call our main office','tel:+13124457787'))+'<section class="container location-directory">'
for l in LOCATIONS:
 locations+=f'<article class="location-card" id="{l["city"].lower()}"><div class="location-code">{l["abbr"]}</div><div>{eyebrow(l["type"].upper())}<h2>{l["city"]}<span>, {l["abbr"]}</span></h2><p>{l["address"]}<br>{l["area"]}</p></div><div>{textlink(l["phone"],"tel:"+l["tel"])}{textlink("Discuss a project","/quote/?region="+l["abbr"])}</div></article>'
locations+='</section><div class="container location-note">Office hours: Monday–Friday, 8:00 AM–4:00 PM. Service availability and scheduling are confirmed by the team.</div>'
page('/locations/','Our locations',locations)

contact=subhero('A REAL CONVERSATION STARTS HERE','Tell us what<br><span>you’re working on.</span>','A new project, a service question or a property portfolio. We’ll help you find the right next step.')+f'''<section class="container contact-layout"><div class="contact-primary">{eyebrow('TALK TO ISAK')}<a class="big-phone" href="tel:+13124457787">(312) 445-7787</a><a class="contact-email" href="mailto:office@isakfire.com">office@isakfire.com {DIAG}</a><div class="contact-details"><div><h3>Headquarters</h3><p>875 N Michigan Ave, Suite 3100<br>Chicago, IL 60610</p></div><div><h3>Office hours</h3><p>Monday–Friday<br>8:00 AM–4:00 PM</p></div><div><h3>Toll free</h3><a href="tel:+18333068200">(833) 306-8200</a></div><div><h3>Project estimates</h3><a href="mailto:sales@isakfire.com">sales@isakfire.com</a></div></div></div><aside class="contact-aside"><span class="large-number">Let’s begin.</span><h2>A little detail.<br>A better starting point.</h2><p>Use our guided planner to bring your project information together before you contact the team.</p>{button('Plan your request','/quote/')}<hr><p>Already working with us?</p>{textlink('Client access','/client-portal/')}{textlink('Pay an invoice',PAY,True)}</aside></section>'''
page('/contact/','Get in touch',contact)

faq_filters='<div class="filter-bar" role="group" aria-label="Filter questions">'+''.join(f'<button data-filter="{g}" aria-pressed="{str(i==0).lower()}">{g}</button>' for i,g in enumerate(['All questions']+list(dict.fromkeys(f['group'] for f in DATA['faqs']))))+'</div>'
resources=subhero('KNOWLEDGE IS PART OF PROTECTION','Clear questions.<br><span>Considered answers.</span>','Explore common questions about working with Isak, planning a project and caring for your systems.')+f'<section class="container resource-content" data-filter-scope>{faq_filters}<label class="search-label" for="faq-search">Search questions<input id="faq-search" type="search" placeholder="Try inspections, kitchen or quote…" data-search></label><div>{faq_items(DATA["faqs"])}</div><p class="empty-message" hidden>No matching questions. Try another term or contact our team.</p><p class="resource-note">Requirements depend on your system, adopted codes and local authority. Ask a qualified professional to confirm the requirements for your property.</p></section>'
page('/resources/','Questions & answers',resources)

news_filter='<div class="filter-bar" role="group" aria-label="Filter insights">'+''.join(f'<button data-filter="{g}" aria-pressed="{str(i==0).lower()}">{g}</button>' for i,g in enumerate(['All insights','Code updates','Fire safety','Company news']))+'</div>'
insights=subhero('FROM THE ISAK JOURNAL','A more informed<br><span>perspective.</span>','Explore the topics in Isak’s published journal. Full articles open on the current company website.')+f'<section class="container insights-content" data-filter-scope>{news_filter}<div class="news-grid">{news_cards(DATA["insights"])}</div></section>'
